pub fn co_by_awbw_id(id: u32) -> Option<&'static CoData> {
    COS.iter().find(|c| c.awbw_id == id)
}

pub fn co_by_name(name: &str) -> Option<&'static CoData> {
    COS.iter().find(|c| c.name.eq_ignore_ascii_case(name))
}
